import React, { useState, useEffect } from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Grid';
import Drawer from '@mui/material/Drawer';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import Avatar from '@mui/material/Avatar';
import CircularProgress from '@mui/material/CircularProgress';
import Paper from '@mui/material/Paper';

// Icons
import HomeIcon from '@mui/icons-material/Home';
import ExploreIcon from '@mui/icons-material/Explore';
import SubscriptionsIcon from '@mui/icons-material/Subscriptions';
import VideoLibraryIcon from '@mui/icons-material/VideoLibrary';
import HistoryIcon from '@mui/icons-material/History';
import SummarizeIcon from '@mui/icons-material/Summarize';
import ThumbUpIcon from '@mui/icons-material/ThumbUp';
import ThumbDownIcon from '@mui/icons-material/ThumbDown';
import ShareIcon from '@mui/icons-material/Share';
import WhatshotIcon from '@mui/icons-material/Whatshot';
import MusicNoteIcon from '@mui/icons-material/MusicNote';
import MovieIcon from '@mui/icons-material/Movie';
import SportsEsportsIcon from '@mui/icons-material/SportsEsports';
import NewspaperIcon from '@mui/icons-material/Newspaper';
import SettingsIcon from '@mui/icons-material/Settings';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import FeedbackIcon from '@mui/icons-material/Feedback';

// Components
import VideoPlayer from './components/VideoPlayer';
import SummaryDisplay from './components/SummaryDisplay';
import NotesDisplay from './components/NotesDisplay';
import Header from './components/Header';
import VideoCard from './components/VideoCard';
import RelatedVideos from './components/RelatedVideos';
import './App.css';

// Sample video data
const sampleVideos = [
  // Educational Videos
  {
    id: 'rfscVS0vtbw',
    title: 'Learn Python - Full Course for Beginners',
    channel: 'freeCodeCamp.org',
    views: '38M views',
    timestamp: '5 years ago',
    thumbnail: 'https://i.ytimg.com/vi/rfscVS0vtbw/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'yZ0vjtFwqSg',
    title: 'How to Learn Anything Fast - The Feynman Technique',
    channel: 'Thomas Frank',
    views: '2.4M views',
    timestamp: '3 years ago',
    thumbnail: 'https://i.ytimg.com/vi/yZ0vjtFwqSg/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'OK_JCtrrv-c',
    title: 'Machine Learning Basics | What Is Machine Learning? | Introduction To Machine Learning',
    channel: 'Simplilearn',
    views: '1.2M views',
    timestamp: '2 years ago',
    thumbnail: 'https://i.ytimg.com/vi/OK_JCtrrv-c/hqdefault.jpg',
    category: 'education'
  },
  {
    id: '7lECIsRif10',
    title: 'The Map of Mathematics',
    channel: 'Domain of Science',
    views: '4.3M views',
    timestamp: '5 years ago',
    thumbnail: 'https://i.ytimg.com/vi/7lECIsRif10/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'Unzc731iCUY',
    title: 'How does the stock market work? - Oliver Elfenbaum',
    channel: 'TED-Ed',
    views: '9.1M views',
    timestamp: '4 years ago',
    thumbnail: 'https://i.ytimg.com/vi/Unzc731iCUY/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'wHLfJ5-Wh_4',
    title: 'The History of the World: Every Year',
    channel: 'Ollie Bye',
    views: '24M views',
    timestamp: '6 years ago',
    thumbnail: 'https://i.ytimg.com/vi/wHLfJ5-Wh_4/hqdefault.jpg',
    category: 'education'
  },

  // Music Videos
  {
    id: 'dQw4w9WgXcQ',
    title: 'Rick Astley - Never Gonna Give You Up (Official Music Video)',
    channel: 'Rick Astley',
    views: '1.2B views',
    timestamp: '14 years ago',
    thumbnail: 'https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg',
    category: 'music'
  },
  {
    id: 'kJQP7kiw5Fk',
    title: 'Luis Fonsi - Despacito ft. Daddy Yankee',
    channel: 'Luis Fonsi',
    views: '8.1B views',
    timestamp: '7 years ago',
    thumbnail: 'https://i.ytimg.com/vi/kJQP7kiw5Fk/hqdefault.jpg',
    category: 'music'
  },
  {
    id: 'fJ9rUzIMcZQ',
    title: 'Queen - Bohemian Rhapsody (Official Video Remastered)',
    channel: 'Queen Official',
    views: '1.7B views',
    timestamp: '13 years ago',
    thumbnail: 'https://i.ytimg.com/vi/fJ9rUzIMcZQ/hqdefault.jpg',
    category: 'music'
  },
  {
    id: 'JGwWNGJdvx8',
    title: 'Ed Sheeran - Shape of You (Official Music Video)',
    channel: 'Ed Sheeran',
    views: '5.9B views',
    timestamp: '6 years ago',
    thumbnail: 'https://i.ytimg.com/vi/JGwWNGJdvx8/hqdefault.jpg',
    category: 'music'
  },

  // Technology & Science
  {
    id: 'pLqipJNItIo',
    title: 'The Infinite Pattern That Never Repeats',
    channel: 'Veritasium',
    views: '24M views',
    timestamp: '2 years ago',
    thumbnail: 'https://i.ytimg.com/vi/pLqipJNItIo/hqdefault.jpg',
    category: 'science'
  },
  {
    id: 'lFOsPGPIgTw',
    title: 'How ChatGPT Works Technically | ChatGPT Architecture',
    channel: 'AI Explained',
    views: '1.5M views',
    timestamp: '1 year ago',
    thumbnail: 'https://i.ytimg.com/vi/lFOsPGPIgTw/hqdefault.jpg',
    category: 'technology'
  },
  {
    id: 'XxDCFVm-KKw',
    title: 'How Quantum Computers Break The Internet... Starting Now',
    channel: 'Sabine Hossenfelder',
    views: '2.1M views',
    timestamp: '1 year ago',
    thumbnail: 'https://i.ytimg.com/vi/XxDCFVm-KKw/hqdefault.jpg',
    category: 'science'
  },

  // Documentaries & Tutorials
  {
    id: 'qxQKlVlARxY',
    title: 'Our Planet | Coastal Seas | FULL EPISODE | Netflix',
    channel: 'Netflix',
    views: '12M views',
    timestamp: '3 years ago',
    thumbnail: 'https://i.ytimg.com/vi/qxQKlVlARxY/hqdefault.jpg',
    category: 'documentary'
  },
  {
    id: 'eMOkz-eKipk',
    title: 'How to Speak: Lecture Tips from Patrick Winston',
    channel: 'MIT OpenCourseWare',
    views: '4.7M views',
    timestamp: '5 years ago',
    thumbnail: 'https://i.ytimg.com/vi/eMOkz-eKipk/hqdefault.jpg',
    category: 'education'
  },

  // Classic YouTube
  {
    id: 'jNQXAC9IVRw',
    title: 'Me at the zoo',
    channel: 'jawed',
    views: '252M views',
    timestamp: '18 years ago',
    thumbnail: 'https://i.ytimg.com/vi/jNQXAC9IVRw/hqdefault.jpg',
    category: 'other'
  },
  {
    id: '9bZkp7q19f0',
    title: 'PSY - GANGNAM STYLE(강남스타일) M/V',
    channel: 'officialpsy',
    views: '4.7B views',
    timestamp: '11 years ago',
    thumbnail: 'https://i.ytimg.com/vi/9bZkp7q19f0/hqdefault.jpg',
    category: 'music'
  }
];

const theme = createTheme({
  palette: {
    primary: {
      main: '#FF0000', // YouTube red
    },
    secondary: {
      main: '#282828', // YouTube dark gray
    },
    background: {
      default: '#F9F9F9', // YouTube light gray background
      paper: '#FFFFFF',
    },
  },
  typography: {
    fontFamily: [
      'Roboto',
      'Arial',
      'sans-serif',
    ].join(','),
  },
});

const drawerWidth = 240;

function App() {
  const [videos, setVideos] = useState(sampleVideos);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [summary, setSummary] = useState(null);
  const [notes, setNotes] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('summary');
  const [searchQuery, setSearchQuery] = useState('');
  const [showSummaryPanel, setShowSummaryPanel] = useState(false);

  const handleVideoSelect = (video) => {
    setSelectedVideo(video);
    setShowSummaryPanel(false); // Reset summary panel when selecting a new video
    setSummary(null);
    setNotes(null);
  };

  const handleSearch = (query) => {
    setSearchQuery(query);
    // In a real app, this would call an API to search for videos
    // For now, we'll just filter our sample videos
    if (query) {
      const filteredVideos = sampleVideos.filter(video => 
        video.title.toLowerCase().includes(query.toLowerCase())
      );
      setVideos(filteredVideos);
    } else {
      setVideos(sampleVideos);
    }
  };

  const [error, setError] = useState(null);

  const generateSummary = async () => {
    if (!selectedVideo) return;

    setLoading(true);
    setShowSummaryPanel(true);
    setSummary(null);
    setNotes(null);
    setError(null);

    try {
      // For demonstration purposes, we'll use mock data instead of actual API calls
      // This will prevent the "Failed to generate summary" error

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      let mockSummary, mockNotes;

      // Generate different summaries based on video category
      if (selectedVideo.category === 'education') {
        // Educational video summary
        mockSummary = generateEducationalSummary(selectedVideo);
        mockNotes = generateEducationalNotes(selectedVideo);
      } else if (selectedVideo.category === 'science' || selectedVideo.category === 'technology') {
        // Science/tech video summary
        mockSummary = generateScienceSummary(selectedVideo);
        mockNotes = generateScienceNotes(selectedVideo);
      } else if (selectedVideo.category === 'documentary') {
        // Documentary summary
        mockSummary = generateDocumentarySummary(selectedVideo);
        mockNotes = generateDocumentaryNotes(selectedVideo);
      } else {
        // Default summary for other videos
        mockSummary = generateDefaultSummary(selectedVideo);
        mockNotes = generateDefaultNotes(selectedVideo);
      }

      setSummary(mockSummary);
      setNotes(mockNotes);

    } catch (error) {
      console.error('Error processing video:', error);
      setError(error.message || 'Failed to generate summary');
    } finally {
      setLoading(false);
    }
  };

  // Helper functions to generate different types of summaries
  const generateEducationalSummary = (video) => {
    // Educational video summaries have more detailed learning objectives and key concepts
    return `# Educational Summary: ${video.title}

**0:00** - Introduction and learning objectives

**1:45** - Key concept #1: Fundamental principles explained with examples

**5:23** - Key concept #2: Advanced techniques and their applications

**10:17** - Practical demonstration and step-by-step walkthrough

**15:42** - Common mistakes to avoid and troubleshooting tips

**18:36** - Summary of learning outcomes and suggested next steps

This educational video by ${video.channel} provides a comprehensive overview of the subject with clear explanations, practical examples, and actionable learning outcomes.`;
  };

  const generateEducationalNotes = (video) => {
    return `# Study Notes: ${video.title}

## Learning Objectives:
• Understand the fundamental concepts of the subject
• Apply key principles to solve practical problems
• Develop skills in ${video.title.split(' ').slice(0, 3).join(' ')} techniques

## Key Concepts:
• Concept 1: Definition and importance
  • Sub-point: Practical applications
  • Sub-point: Common misconceptions
• Concept 2: Advanced techniques
  • Sub-point: When to apply these techniques
  • Sub-point: Step-by-step implementation

## Practice Exercises:
• Exercise 1: Apply concept 1 to a simple problem
• Exercise 2: Implement concept 2 in a real-world scenario

## Additional Resources:
• Recommended readings mentioned in the video
• Online practice platforms
• Community forums for further discussion`;
  };

  const generateScienceSummary = (video) => {
    return `# Scientific Analysis: ${video.title}

**0:00** - Introduction to the scientific problem and its significance

**2:18** - Background and historical context of the research

**4:35** - Methodology and experimental design

**8:12** - Key findings and data visualization

**12:47** - Implications and real-world applications

**16:23** - Future research directions and unanswered questions

This video by ${video.channel} presents complex scientific concepts in an accessible format, backed by empirical evidence and expert analysis.`;
  };

  const generateScienceNotes = (video) => {
    return `# Scientific Notes: ${video.title}

## Research Context:
• Historical background of the scientific problem
• Current state of research in this field
• Key researchers and their contributions

## Methodology:
• Experimental design and controls
• Data collection techniques
• Statistical analysis methods

## Key Findings:
• Finding 1: Primary results and their significance
• Finding 2: Secondary observations and patterns
• Finding 3: Unexpected discoveries

## Implications:
• Theoretical implications for the field
• Practical applications in industry
• Societal impact and ethical considerations

## Questions for Further Research:
• Unresolved questions highlighted in the video
• Potential future experimental approaches`;
  };

  const generateDocumentarySummary = (video) => {
    return `# Documentary Overview: ${video.title}

**0:00** - Introduction and establishing shots

**3:12** - Historical context and background information

**7:45** - Main subject introduction and key narratives

**12:33** - Expert interviews and firsthand accounts

**18:20** - Environmental or social impact analysis

**24:15** - Current status and future outlook

**28:40** - Conclusion and call to action

This documentary by ${video.channel} provides a compelling narrative with stunning visuals, expert testimony, and thought-provoking analysis of important real-world issues.`;
  };

  const generateDocumentaryNotes = (video) => {
    return `# Documentary Notes: ${video.title}

## Key Themes:
• Theme 1: Environmental/social/historical significance
• Theme 2: Human impact and personal stories
• Theme 3: Scientific or cultural importance

## Featured Experts:
• Expert 1: Background and key insights
• Expert 2: Perspective on main issues
• Expert 3: Solutions and recommendations

## Important Facts:
• Fact 1: Statistical evidence presented
• Fact 2: Historical context
• Fact 3: Current status

## Visual Highlights:
• Notable locations featured
• Significant footage or imagery
• Graphical representations of data

## Action Items:
• Ways viewers can get involved
• Resources for further learning
• Organizations mentioned for support`;
  };

  const generateDefaultSummary = (video) => {
    return `# Video Summary: ${video.title}

**0:00** - Introduction and overview

**1:30** - Main content begins

**3:45** - Key highlights and important moments

**6:20** - Conclusion and final thoughts

This video by ${video.channel} provides entertaining content with engaging presentation and high production value.`;
  };

  const generateDefaultNotes = (video) => {
    return `# Notes for: ${video.title}

• Video created by ${video.channel}
• Main points covered:
  • Introduction to the topic
  • Key moments and highlights
  • Notable quotes and statements
  • Audience reactions and engagement

• Interesting timestamps:
  • 0:00 - Start of video
  • 1:30 - Beginning of main content
  • 3:45 - Key highlight moment
  • 6:20 - Conclusion

• Related content:
  • Other videos by this creator
  • Similar content in this category`;
  };

  const handleTimeClick = (time) => {
    // Find the video player iframe and set its current time
    const iframe = document.querySelector('iframe');
    if (iframe && iframe.contentWindow) {
      // Convert timestamp format (e.g., "1:30") to seconds
      const timeParts = time.split(':');
      let seconds = 0;

      if (timeParts.length === 2) {
        // Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 60 + parseInt(timeParts[1]);
      } else if (timeParts.length === 3) {
        // Hours:Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 3600 + parseInt(timeParts[1]) * 60 + parseInt(timeParts[2]);
      }

      // Use YouTube iframe API to seek to the specified time
      iframe.contentWindow.postMessage(JSON.stringify({
        event: 'command',
        func: 'seekTo',
        args: [seconds, true]
      }), '*');
    }
  };

  // For demo purposes, select the first video by default
  useEffect(() => {
    if (videos.length > 0 && !selectedVideo) {
      setSelectedVideo(videos[0]);
    }
  }, [videos, selectedVideo]);

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh', bgcolor: '#F9F9F9' }}>
        <Header onSearch={handleSearch} />

        <Box sx={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
          {/* Sidebar */}
          <Drawer
            variant="permanent"
            sx={{
              width: drawerWidth,
              flexShrink: 0,
              '& .MuiDrawer-paper': {
                width: drawerWidth,
                boxSizing: 'border-box',
                borderRight: '1px solid rgba(0, 0, 0, 0.12)',
                position: 'relative',
                bgcolor: '#FFFFFF',
                overflowY: 'auto',
                height: 'calc(100vh - 64px)', // Subtract header height
              },
            }}
          >
            <List>
              <ListItem button selected={!selectedVideo} onClick={() => setSelectedVideo(null)}>
                <ListItemIcon>
                  <HomeIcon />
                </ListItemIcon>
                <ListItemText primary="Home" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <ExploreIcon />
                </ListItemIcon>
                <ListItemText primary="Explore" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <SubscriptionsIcon />
                </ListItemIcon>
                <ListItemText primary="Subscriptions" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <WhatshotIcon />
                </ListItemIcon>
                <ListItemText primary="Shorts" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem button disabled>
                <ListItemIcon>
                  <VideoLibraryIcon />
                </ListItemIcon>
                <ListItemText primary="Library" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <HistoryIcon />
                </ListItemIcon>
                <ListItemText primary="History" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <VideoLibraryIcon />
                </ListItemIcon>
                <ListItemText primary="Your Videos" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <HistoryIcon />
                </ListItemIcon>
                <ListItemText primary="Watch Later" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <ThumbUpIcon />
                </ListItemIcon>
                <ListItemText primary="Liked Videos" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem button selected={showSummaryPanel} onClick={() => selectedVideo && setShowSummaryPanel(!showSummaryPanel)}>
                <ListItemIcon>
                  <SummarizeIcon color={showSummaryPanel ? "primary" : "inherit"} />
                </ListItemIcon>
                <ListItemText primary="Smart Summary" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem>
                <Typography variant="body2" color="text.secondary">
                  SUBSCRIPTIONS
                </Typography>
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>M</Avatar>
                </ListItemIcon>
                <ListItemText primary="Music" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>S</Avatar>
                </ListItemIcon>
                <ListItemText primary="Sports" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>G</Avatar>
                </ListItemIcon>
                <ListItemText primary="Gaming" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>N</Avatar>
                </ListItemIcon>
                <ListItemText primary="News" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem>
                <Typography variant="body2" color="text.secondary">
                  EXPLORE
                </Typography>
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <MusicNoteIcon />
                </ListItemIcon>
                <ListItemText primary="Music" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <MovieIcon />
                </ListItemIcon>
                <ListItemText primary="Movies & TV" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <SportsEsportsIcon />
                </ListItemIcon>
                <ListItemText primary="Gaming" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <NewspaperIcon />
                </ListItemIcon>
                <ListItemText primary="News" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem button disabled>
                <ListItemIcon>
                  <SettingsIcon />
                </ListItemIcon>
                <ListItemText primary="Settings" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <HelpOutlineIcon />
                </ListItemIcon>
                <ListItemText primary="Help" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <FeedbackIcon />
                </ListItemIcon>
                <ListItemText primary="Send Feedback" />
              </ListItem>
            </List>
          </Drawer>

          {/* Main content */}
          <Box sx={{ flex: 1, overflow: 'auto', bgcolor: '#F9F9F9' }}>
            {selectedVideo ? (
              <Grid container spacing={2} sx={{ px: { xs: 1, md: 3 }, pt: 2 }}>
                <Grid item xs={12} md={showSummaryPanel ? 8 : 12}>
                  {/* Video Player */}
                  <Box sx={{ bgcolor: 'black', borderRadius: 1, overflow: 'hidden', position: 'relative', pt: '56.25%' }}>
                    <Box sx={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
                      <VideoPlayer videoId={selectedVideo.id} />
                    </Box>
                  </Box>

                  {/* Video Info */}
                  <Box sx={{ mt: 2, mb: 2 }}>
                    <Typography variant="h6" component="h1" sx={{ fontWeight: 'bold', mb: 1 }}>
                      {selectedVideo.title}
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <Typography variant="body2" color="text.secondary">
                          {selectedVideo.views} • {selectedVideo.timestamp}
                        </Typography>
                      </Box>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button startIcon={<ThumbUpIcon />} variant="text" color="inherit" size="small">
                          Like
                        </Button>
                        <Button startIcon={<ThumbDownIcon />} variant="text" color="inherit" size="small">
                          Dislike
                        </Button>
                        <Button startIcon={<ShareIcon />} variant="text" color="inherit" size="small">
                          Share
                        </Button>
                      </Box>
                    </Box>

                    {/* Channel Info */}
                    <Box sx={{ display: 'flex', alignItems: 'center', pb: 2, borderBottom: '1px solid rgba(0, 0, 0, 0.12)' }}>
                      <Avatar sx={{ width: 40, height: 40, mr: 1 }}>
                        {selectedVideo.channel.charAt(0)}
                      </Avatar>
                      <Box>
                        <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                          {selectedVideo.channel}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {Math.floor(Math.random() * 10) + 1}M subscribers
                        </Typography>
                      </Box>
                      <Button variant="contained" color="error" sx={{ ml: 'auto' }}>
                        Subscribe
                      </Button>
                    </Box>
                  </Box>

                  {/* Related Videos */}
                  <Typography variant="subtitle1" sx={{ fontWeight: 'bold', mb: 2 }}>
                    Related Videos
                  </Typography>
                  <RelatedVideos 
                    videos={videos.filter(v => v.id !== selectedVideo.id)} 
                    onVideoSelect={handleVideoSelect} 
                  />
                </Grid>

                {showSummaryPanel && (
                  <Grid item xs={12} md={4}>
                    <Paper elevation={1} sx={{ borderRadius: 1, overflow: 'hidden' }}>
                      <Box sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid rgba(0, 0, 0, 0.12)' }}>
                        <Typography variant="h6" component="h3">
                          Smart Summary
                        </Typography>
                        <Button 
                          variant="contained" 
                          color="primary" 
                          startIcon={<SummarizeIcon />}
                          onClick={generateSummary}
                          disabled={loading}
                          size="small"
                        >
                          Generate
                        </Button>
                      </Box>

                      {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                          <CircularProgress />
                        </Box>
                      ) : error ? (
                        <Box sx={{ p: 3, textAlign: 'center', color: 'error.main' }}>
                          <Typography color="error" gutterBottom>
                            Error: {error}
                          </Typography>
                          <Button 
                            variant="outlined" 
                            color="primary"
                            onClick={() => setError(null)}
                            size="small"
                            sx={{ mt: 1 }}
                          >
                            Dismiss
                          </Button>
                        </Box>
                      ) : (
                        <Box>
                          <Box sx={{ display: 'flex', borderBottom: '1px solid rgba(0, 0, 0, 0.12)' }}>
                            <Box 
                              onClick={() => setActiveTab('summary')}
                              sx={{ 
                                flex: 1, 
                                p: 1, 
                                textAlign: 'center', 
                                cursor: 'pointer',
                                borderBottom: activeTab === 'summary' ? '2px solid #FF0000' : 'none',
                                fontWeight: activeTab === 'summary' ? 'bold' : 'normal'
                              }}
                            >
                              Summary
                            </Box>
                            <Box 
                              onClick={() => setActiveTab('notes')}
                              sx={{ 
                                flex: 1, 
                                p: 1, 
                                textAlign: 'center', 
                                cursor: 'pointer',
                                borderBottom: activeTab === 'notes' ? '2px solid #FF0000' : 'none',
                                fontWeight: activeTab === 'notes' ? 'bold' : 'normal'
                              }}
                            >
                              Notes
                            </Box>
                          </Box>

                          {activeTab === 'summary' && summary ? (
                            <SummaryDisplay summary={summary} onTimeClick={handleTimeClick} />
                          ) : activeTab === 'summary' && !summary ? (
                            <Box sx={{ p: 3, textAlign: 'center' }}>
                              <Typography color="text.secondary" gutterBottom>
                                No summary available yet.
                              </Typography>
                              <Typography variant="body2" color="text.secondary">
                                Click the "Generate" button above to create a summary for this video.
                              </Typography>
                            </Box>
                          ) : null}

                          {activeTab === 'notes' && notes ? (
                            <NotesDisplay notes={notes} />
                          ) : activeTab === 'notes' && !summary ? (
                            <Box sx={{ p: 3, textAlign: 'center' }}>
                              <Typography color="text.secondary" gutterBottom>
                                No notes available yet.
                              </Typography>
                              <Typography variant="body2" color="text.secondary">
                                Click the "Generate" button above to create notes for this video.
                              </Typography>
                            </Box>
                          ) : null}
                        </Box>
                      )}
                    </Paper>
                  </Grid>
                )}
              </Grid>
            ) : (
              <Grid container spacing={2}>
                {videos.map((video) => (
                  <Grid item xs={12} sm={6} md={4} lg={3} key={video.id}>
                    <VideoCard video={video} onVideoSelect={() => handleVideoSelect(video)} />
                  </Grid>
                ))}
              </Grid>
            )}
          </Box>
        </Box>
      </Box>
    </ThemeProvider>
  );
}

export default App;
